import {quotePrice,quoteInputs} from './quote-core.js';
export function setupQuotes(onSave){
 const $=id=>document.getElementById(id),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 let item=null,context=null;
 $('quoteMethod').insertAdjacentHTML('beforeend','<option value="manual">직접 입력 단가</option>');
 $('quoteRows').insertAdjacentHTML('afterend',`<div class="assembly-tools quote-extra"><label>적용일 <input id="quoteDate" type="date"></label><label>끝자리 처리 <select id="quoteRounding"><option value="none">처리 안 함</option><option value="floor">절하</option><option value="ceil">절상</option><option value="round">반올림</option></select></label><label>자릿수 <select id="quoteDigits"><option value="-3">천 원</option><option value="-2">백 원</option><option value="-1">십 원</option><option value="0">원</option><option value="1">소수 1자리</option><option value="2">소수 2자리</option></select></label><label>직접 입력 <input id="quoteManual" type="number" min="0" step="any" aria-label="직접 입력 단가"></label><label>부가세 처리 <select id="quoteVat"><option value="none">변환 안 함</option><option value="exclude">포함가 → 공급가</option><option value="include">공급가 → 포함가</option></select></label><label>세율 <input id="quoteVatRate" type="number" min="0" step="any" value="10" aria-label="단가 부가세율">%</label><label>자재 구분 <select id="quoteSupply"><option value="general">일반</option><option value="private">사급</option><option value="government">관급</option></select></label></div>`);

 const values=()=>[...$('quoteRows').querySelectorAll('[data-quote]')].map(e=>e.value.trim()===''?null:Number(e.value));
 function result(){return quotePrice(values(),{method:$('quoteMethod').value,selected:Number($('quoteSelected').value),manual:$('quoteManual').value,vat:$('quoteVat').value,vatRate:$('quoteVatRate').value,rounding:$('quoteRounding').value,digits:Number($('quoteDigits').value)});}

 function preview(){try{$('quoteResult').textContent='적용 단가 '+result().toLocaleString('ko-KR',{maximumFractionDigits:8})+'원';$('quoteSave').disabled=false;}catch(e){$('quoteResult').textContent=e.message;$('quoteSave').disabled=true;}}
 for(const id of ['quoteManual','quoteVat','quoteVatRate','quoteSupply','quoteRounding','quoteDigits'])$(id).oninput=preview;
 $('quoteRows').oninput=preview;$('quoteMethod').onchange=preview;$('quoteSelected').onchange=preview;
 $('quoteSave').onclick=async()=>{try{const price=result(),key=item.category==='노임'?'labor':'material';const rate={...structuredClone(item),id:crypto.randomUUID(),code:'USER-'+Date.now(),source:'나의 단가',table:'UserQuote',record:0,labor:0,material:0,expense:0,other:0,total:price,[key]:price,prices:values(),quoteSources:[...$('quoteRows').querySelectorAll('[data-quote-source]')].map(el=>el.value.trim()),quotePages:[...$('quoteRows').querySelectorAll('[data-quote-page]')].map(el=>el.value.trim()),quoteDate:$('quoteDate').value,quoteRounding:{mode:$('quoteRounding').value,digits:Number($('quoteDigits').value)},supply:$('quoteSupply').value,government:$('quoteSupply').value==='government',vatConversion:{mode:$('quoteVat').value,rate:Number($('quoteVatRate').value)},quoteManual:$('quoteManual').value,quoteMethod:$('quoteMethod').value,quoteSelection:Number($('quoteSelected').value),origin:{source:item.source,code:item.code}};delete rate.components;delete rate.calculation;$('quoteSave').disabled=true;await onSave(rate,$('quoteApplyLine').checked?context:null);$('quoteDialog').close();}catch(e){$('quoteResult').textContent=e.message;$('quoteSave').disabled=false;}};
 return {open(rate,labels=[],target=null){item=rate;context=target;const initial=quoteInputs(rate);$('quoteTitle').textContent=rate.name+' · 조사단가 비교';$('quoteRows').innerHTML='<table><thead><tr><th>번호</th><th>자료 · 업체</th><th>조사단가</th><th>페이지 · 근거</th></tr></thead><tbody>'+Array.from({length:6},(_,i)=>`<tr><td>${i+1}</td><td><input data-quote-source="${i}" value="${esc(rate.quoteSources?.[i]??labels[i]??'조사단가 '+(i+1))}" aria-label="조사 출처 ${i+1}"></td><td><input type="number" min="0" step="any" data-quote="${i}" value="${initial.prices[i]??''}" aria-label="조사단가 ${i+1}"></td><td><input data-quote-page="${i}" value="${esc(rate.quotePages?.[i]||'')}" aria-label="조사 근거 ${i+1}"></td></tr>`).join('')+'</tbody></table>';$('quoteApplyLabel').hidden=!context;$('quoteApplyLine').checked=!!context;$('quoteMethod').value=initial.method;$('quoteSelected').value=String(rate.quoteSelection||0);$('quoteManual').value=rate.quoteManual??rate.total;$('quoteDate').value=rate.quoteDate||'';$('quoteRounding').value=rate.quoteRounding?.mode||(rate.vatConversion?.mode&&rate.vatConversion.mode!=='none'?'floor':'none');$('quoteDigits').value=String(rate.quoteRounding?.digits??0);$('quoteVat').value=rate.vatConversion?.mode||'none';$('quoteVatRate').value=rate.vatConversion?.rate??10;$('quoteSupply').value=rate.supply||(rate.government?'government':'general');preview();$('quoteDialog').showModal();}};
}
